SourceCode.Declaration:
/// <summary>
/// This is a contarct class for vendor change request batch job.
/// </summary>
[DataContractAttribute]
class METVendorChangeRequestContract
{
    InventSiteId inventSiteId;
    ItemId      itemId;
    boolean     calledFromPackChange;

}

Method.Source:
    /// <summary>
    /// This is a parameter for site id.
    /// </summary>
    /// <param name = "_inventSiteId">_inventSiteId</param>
    /// <returns>Returns the site information.</returns>
    [DataMemberAttribute,
        SysOperationLabelAttribute('@ElectronicReporting:Site'),
        SysOperationDisplayOrderAttribute('1')]
    public InventSiteId parmInventSiteId(InventSiteId _inventSiteId = inventSiteId)
    {
        inventSiteId = _inventSiteId;

        return inventSiteId;
    }

    /// <summary>
    /// Item Id parameter
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>ItemId</returns>    
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public ItemId parmItemId(ItemId _itemId = itemId)
    {
        itemId = _itemId;

        return itemId;
    }

    /// <summary>
    /// Called from pack change parameter
    /// </summary>
    /// <param name = "_calledFromDefaultForm">true or false</param>
    /// <returns>true or false</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public boolean parmCalledFromDefaultForm(boolean _calledFromPackChange = calledFromPackChange)
    {
        calledFromPackChange = _calledFromPackChange;

        return _calledFromPackChange;
    }
